const crypto = require('crypto');

const input = $input.first().json;
const headers = input.headers || {};
const query = input.query || {};
const body = input.body || input;

// Orders API (Checkout Pro): la notificacion llega con topic `orders_v2`,
// type `order`, y data.id = id de la ORDEN (query param y body).
const dataId = query['data.id'] || (body.data && body.data.id) || body.id;
const requestId = headers['x-request-id'] || '';
const signatureHeader = headers['x-signature'] || '';

if (!dataId) {
  throw new Error('MP webhook: missing data.id');
}

// x-signature format: "ts=1704908010,v1=618c85..."
const parts = {};
for (const chunk of String(signatureHeader).split(',')) {
  const idx = chunk.indexOf('=');
  if (idx > -1) parts[chunk.slice(0, idx).trim()] = chunk.slice(idx + 1).trim();
}
const ts = parts.ts;
const v1 = parts.v1;
if (!ts || !v1) {
  throw new Error('MP webhook: missing ts/v1 in x-signature');
}

const secret = $env.MP_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('MP_WEBHOOK_SECRET env var is not set');
}

// TODO(verify): manifest template per Mercado Pago docs:
//   id:[data.id];request-id:[x-request-id];ts:[ts];  (id en minusculas)
// Orders API: el id de la orden (ej. ORD01JQ...) debe ir en MINUSCULAS en el
// manifiesto, o la firma nunca coincide. Verificado en la doc de MP (Orders API).
const manifestId = String(dataId).toLowerCase();
const manifest = 'id:' + manifestId + ';request-id:' + requestId + ';ts:' + ts + ';';
const hmac = crypto.createHmac('sha256', secret).update(manifest).digest('hex');
if (hmac !== v1) {
  throw new Error('MP webhook: invalid x-signature');
}

// Order code: LAT-XXXXXX (base32, no ambiguous characters).
// Generated here so downstream nodes (email) can reuse it.
const alphabet = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
let suffix = '';
for (const byte of crypto.randomBytes(6)) {
  suffix += alphabet[byte % alphabet.length];
}

return [{ json: { valid: true, paymentId: String(dataId), requestId, ts, orderCode: 'LAT-' + suffix } }];

const payment = $input.first().json;
const orderCode = $('Validate MP Signature').item.json.orderCode;
const payer = payment.payer || {};
const buyerName = [payer.first_name, payer.last_name].filter(Boolean).join(' ').trim();
const amount = payment.transaction_amount !== undefined && payment.transaction_amount !== null
  ? Math.round(Number(payment.transaction_amount))
  : null;
const payload = {
  order_code: orderCode,
  mp_payment_id: payment.id !== undefined && payment.id !== null ? String(payment.id) : null,
  mp_status: payment.status || null,
  external_reference: payment.external_reference || null,
  buyer_name: buyerName || null,
  buyer_email: payer.email || null,
  amount_cop: amount,
};

// Single JSON payload -> the Postgres node uses one parameterized $1::jsonb.
// TODO(latido): keep this in sync with the orders columns in PLAN.md 10.
return [{ json: { orderPayload: JSON.stringify(payload) } }];
